const products = $('Load Approved Products').all().map(i => i.json || {});
const htmlItem = $input.first()?.json || {};
const html = String(htmlItem.data || htmlItem.body || '');
let followers = 1395;
let ttSeller = false;
let commerceUser = false;
const m = html.match(/<script id="__UNIVERSAL_DATA_FOR_REHYDRATION__"[^>]*>(.*?)<\/script>/);
if (m) {
  try {
    const parsed = JSON.parse(m[1]);
    const ui = parsed?.__DEFAULT_SCOPE__?.['webapp.user-detail']?.userInfo || {};
    followers = Number(ui?.stats?.followerCount || followers);
    ttSeller = Boolean(ui?.user?.ttSeller);
    commerceUser = Boolean(ui?.user?.commerceUserInfo?.commerceUser);
  } catch (e) {}
}
const delta = Math.max(0, 1500 - followers);
const ctaMode = followers >= 1500 ? 'tiktok_shop_cart' : 'follower_sprint_1500';
const approved = products.filter(p => p.status === 'approved');
return approved.map(p => ({
  json: {
    product_key: p.product_key,
    product_name: p.product_name,
    category: p.category,
    price_eur: p.price_eur,
    commission_pct: p.commission_pct,
    problem_solved: p.problem_solved,
    key_specs: p.key_specs,
    account_followers: followers,
    followers_delta_to_1500: delta,
    recommended_cta_mode: ctaMode
  }
}));
